evt = on("DataSubjectErasureRequest")
subject = sys.acquire("DataSubject", {"id": evt["dataSubjectId"]})
if subject == None:
    sys.emit("RequestDenied", {"requestId": evt["requestId"], "reason": "identity-not-verified"})
else:
    records = sys.acquire("PersonalData", {"dataSubjectId": evt["dataSubjectId"]})
    has_exemption = records["hasLegalRetentionObligation"] or records["requiredForLegalClaim"]
    if has_exemption:
        sys.emit("ErasureRefused", {
            "requestId": evt["requestId"],
            "reason": "legal-exemption",
            "exemptionBasis": records["exemptionBasis"]
        })
    else:
        result = sys.delete("PersonalData", {"dataSubjectId": evt["dataSubjectId"]})
        sys.emit("ErasureCompleted", {
            "requestId": evt["requestId"],
            "dataSubjectId": evt["dataSubjectId"],
            "erasedAt": now()
        })

evt = on("DataSubjectRectificationRequest")
subject = sys.acquire("DataSubject", {"id": evt["dataSubjectId"]})
if subject == None:
    sys.emit("RequestDenied", {"requestId": evt["requestId"], "reason": "identity-not-verified"})
else:
    result = sys.modify("PersonalData", {
        "dataSubjectId": evt["dataSubjectId"]
    }, {
        "correctedFields": evt["corrections"]
    })
    sys.emit("RectificationCompleted", {
        "requestId": evt["requestId"],
        "dataSubjectId": evt["dataSubjectId"],
        "correctedFields": evt["corrections"],
        "rectifiedAt": now()
    })
    sys.emit("RecipientNotificationRequired", {
        "dataSubjectId": evt["dataSubjectId"],
        "action": "rectification",
        "correctedFields": evt["corrections"]
    })

evt = on("DataSubjectPortabilityRequest")
subject = sys.acquire("DataSubject", {"id": evt["dataSubjectId"]})
if subject == None:
    sys.emit("RequestDenied", {"requestId": evt["requestId"], "reason": "identity-not-verified"})
else:
    records = sys.acquire("PersonalData", {"dataSubjectId": evt["dataSubjectId"]})
    export = sys.create("DataExport", {
        "dataSubjectId": evt["dataSubjectId"],
        "format": "structured",
        "content": records,
        "exportedAt": now()
    })
    if evt["directTransfer"] and evt["targetController"]:
        sys.emit("DirectTransferInitiated", {
            "requestId": evt["requestId"],
            "targetController": evt["targetController"],
            "exportId": export["id"]
        })
    else:
        sys.emit("PortabilityExportReady", {
            "requestId": evt["requestId"],
            "exportId": export["id"]
        })

evt = on("DataSubjectObjection")
subject = sys.acquire("DataSubject", {"id": evt["dataSubjectId"]})
if subject == None:
    sys.emit("RequestDenied", {"requestId": evt["requestId"], "reason": "identity-not-verified"})
else:
    activity = sys.acquire("DataProcessingActivity", {"id": evt["processingActivityId"]})
    if activity["lawfulBasis"] == "direct-marketing":
        result = sys.modify("DataProcessingActivity", {
            "id": evt["processingActivityId"]
        }, {
            "status": "ceased",
            "ceaseReason": "data-subject-objection-direct-marketing"
        })
        sys.emit("ObjectionAccepted", {
            "requestId": evt["requestId"],
            "processingActivityId": evt["processingActivityId"]
        })
    elif activity["hasCompellingLegitimateGrounds"]:
        sys.emit("ObjectionRefused", {
            "requestId": evt["requestId"],
            "reason": "compelling-legitimate-grounds",
            "grounds": activity["legitimateGrounds"]
        })
    else:
        result = sys.modify("DataProcessingActivity", {
            "id": evt["processingActivityId"]
        }, {
            "status": "ceased",
            "ceaseReason": "data-subject-objection"
        })
        sys.emit("ObjectionAccepted", {
            "requestId": evt["requestId"],
            "processingActivityId": evt["processingActivityId"]
        })

evt = on("DataSubjectRestrictionRequest")
subject = sys.acquire("DataSubject", {"id": evt["dataSubjectId"]})
if subject == None:
    sys.emit("RequestDenied", {"requestId": evt["requestId"], "reason": "identity-not-verified"})
else:
    result = sys.modify("PersonalData", {
        "dataSubjectId": evt["dataSubjectId"]
    }, {
        "processingRestricted": True,
        "restrictionReason": evt["reason"],
        "restrictedAt": now()
    })
    sys.emit("RestrictionApplied", {
        "requestId": evt["requestId"],
        "dataSubjectId": evt["dataSubjectId"]
    })

evt = on("DataProcessingActivityCreated")
activity = sys.acquire("DataProcessingActivity", {"id": evt["activityId"]})
lawful_bases = ["consent", "contract", "legal-obligation", "vital-interests", "public-interest", "legitimate-interests"]
if activity["lawfulBasis"] not in lawful_bases:
    sys.emit("LawfulnessViolation", {
        "activityId": evt["activityId"],
        "declaredBasis": activity["lawfulBasis"],
        "validBases": lawful_bases,
        "severity": "ERROR"
    })
else:
    sys.emit("LawfulnessValidated", {
        "activityId": evt["activityId"],
        "lawfulBasis": activity["lawfulBasis"]
    })

evt = on("ConsentWithdrawn")
activities = sys.acquire("DataProcessingActivity", {
    "dataSubjectId": evt["dataSubjectId"],
    "lawfulBasis": "consent"
})
for activity_id in activities["ids"]:
    alt_basis = sys.acquire("DataProcessingActivity", {"id": activity_id})
    if not alt_basis["hasAlternativeLawfulBasis"]:
        result = sys.modify("DataProcessingActivity", {
            "id": activity_id
        }, {
            "status": "ceased",
            "ceaseReason": "consent-withdrawn",
            "ceasedAt": now()
        })
        sys.emit("ProcessingCeasedDueToConsentWithdrawal", {
            "activityId": activity_id,
            "dataSubjectId": evt["dataSubjectId"]
        })
